cd /tmp/vally-eval-trial-dAwzVy && P=.copilot-tracking/skraft-plans/pricing && mkdir -p $P/features $P/details/2026-11-25 tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $P/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty discount at checkout
  A returning customer's loyalty tier is reflected in the checkout total.

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price for a basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price for a basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price for a basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer with a tiny basket is charged a whole cent amount
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/CalculateLoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class CalculateLoyaltyDiscountAcceptanceTests
{
    private static int ChargedCents(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Bronze customer is charged the Bronze price for a basket
    [Fact]
    public void S1_BronzeBasketOf10000IsChargedNinetyFiveHundred() =>
        Assert.Equal(9500, ChargedCents(LoyaltyTier.Bronze, 10000));

    // Silver customer is charged the Silver price for a basket
    [Fact]
    public void S2_SilverBasketOf10000IsChargedNineThousand() =>
        Assert.Equal(9000, ChargedCents(LoyaltyTier.Silver, 10000));

    // Gold customer is charged the Gold price for a basket
    [Fact]
    public void S3_GoldBasketOf10000IsChargedEightyFiveHundred() =>
        Assert.Equal(8500, ChargedCents(LoyaltyTier.Gold, 10000));

    // Bronze customer with a tiny basket is charged a whole cent amount
    [Fact]
    public void S4_BronzeBasketOf7IsChargedSeven() =>
        Assert.Equal(7, ChargedCents(LoyaltyTier.Bronze, 7));
}
EOF
dotnet test --nologo 2>&1 | grep -E "Failed |Passed |error|Assert|Expected|Actual|Total|Passed!|Failed!" | head -30; git rev-parse HEAD

